import{_ as t,c as o,o as a,b0 as c}from"./chunks/framework.CLL9SSSf.js";const l="/linux-driver-docs/assets/image-20250105194754452.CzsQGyQV.png",u=JSON.parse('{"title":"LV050-kobject-kset与ktype","description":null,"frontmatter":{"title":"LV050-kobject-kset与ktype","date":"2026-01-19T11:22:51.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/drv-base/dev-model/126d2d33ea3b1e8cd2eac6e8","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2026-01-19T11:22:51.488Z","fulluuid":"cd2eac6e8fc8420dbd066b51202ed286","useduuid":"cd2eac6e8"}},"headers":[],"relativePath":"sdoc/drv-base/dev-model/126d2d33ea3b1e8cd2eac6e8.md","filePath":"sdoc/05-设备驱动基础/15-设备模型/LV050-kobject-kset与ktype.md","lastUpdated":1769002717000}'),k={name:"sdoc/drv-base/dev-model/126d2d33ea3b1e8cd2eac6e8.md"};function s(r,e,d,i,n,b){return a(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="lv050-kobject-kset与ktype" tabindex="-1">LV050-kobject-kset与ktype <a class="header-anchor" href="#lv050-kobject-kset与ktype" aria-label="Permalink to &quot;LV050-kobject-kset与ktype&quot;">​</a></h1><p>kobject 是 Linux 设备模型的基本单元，也是设备模型中最难理解的一部分，可参考内核文档 <a href="https://elixir.bootlin.com/linux/v4.19.71/source/Documentation/kobject.txt" target="_blank" rel="noreferrer">kobject.txt - Documentation/kobject.txt</a>，内核文档好像是参考这个的：<a href="https://lwn.net/Articles/51437/" target="_blank" rel="noreferrer">The zen of kobjects LWN</a>。</p><h2 id="一、kobject、kset-和-ktype" tabindex="-1">一、kobject、kset 和 ktype <a class="header-anchor" href="#一、kobject、kset-和-ktype" aria-label="Permalink to &quot;一、kobject、kset 和 ktype&quot;">​</a></h2><p>这里先引出三个概念：kobject、kset 和 ktype，在开始这一节的学习前，先大概了解一下：</p><ul><li>kobject 是基本数据类型，每个 kobject 都会在 &quot;/sys/“文件系统中以目录的形式出现。</li><li>kset 是一个特殊的 kobject（因此它也会在 &quot;/sys/“文件系统中以目录的形式出现），它用来集合相似的 kobject（这些 kobject 可以是相同属性的，也可以不同属性的）。</li><li>ktype 代表 kobject（严格地讲，是包含了 kobject 的数据结构）的属性操作集合。由于通用性，多个 kobject 可能共用同一个属性操作集，因此把 ktype 独立出来了。每个 kobject 都会指定一个 ktype（包括 kset 内嵌的 kobject）。</li></ul><h2 id="二、有什么关系" tabindex="-1">二、有什么关系？ <a class="header-anchor" href="#二、有什么关系" aria-label="Permalink to &quot;二、有什么关系？&quot;">​</a></h2><p>三者的关系大概如下：</p><img src="'+l+'" alt="image-20250105194754452"><ul><li>kset 可批量管理 kobject。</li><li>kset 继承自 kobject，且将一组 kobject 串连成一个链表进行统一管理。</li><li>kobject 既可以通过 parent 指针找到上层 kobject，也可以通过 kset 指针找到其上层 kset。但上层 kobject 对象无法遍历到下层，所以较少使用。</li></ul>',9)])])}const j=t(k,[["render",s]]);export{u as __pageData,j as default};
